it('detects and executes an inferred npm build from the nested invocation cwd', async () => {
      await createChange(tmpDir, 'nested-inferred-build', buildYaml);
      await writeFile(
        path.join(tmpDir, 'package.json'),
        JSON.stringify({ scripts: { build: 'node -e "process.exit(23)"' } }),
      );
      const nested = path.join(tmpDir, 'packages', 'app');
      await writeFile(path.join(tmpDir, '.gitignore'), 'nested-build-ran\n');
      await writeFile(
        path.join(nested, 'package.json'),
        JSON.stringify({
          scripts: {
            build: "node -e \"require('fs').writeFileSync('nested-build-ran', 'ok')\"",
          },
        }),
      );

      const result = runNode(nested, guardScript, ['nested-inferred-build', 'build']);

      expect(result.status, result.stderr).toBe(0);
      expect(await fs.readFile(path.join(nested, 'nested-build-ran'), 'utf8')).toBe('ok');
      await expect(fs.access(path.join(tmpDir, 'nested-build-ran'))).rejects.toMatchObject({
        code: 'ENOENT',
      });
    })

it('auto-runs the single workspace package build when the root has none', async () => {
    const dir = await makeProject();
    const cli = (...args: string[]) =>
      withClassicCommandContext({ projectRoot: dir, invocationCwd: dir }, () =>
        runClassicCli(args),
      );
    expect(
      (
        await cli(
          'state',
          'init',
          'demo',
          'hotfix',
          '--isolation',
          'current',
          '--runtime',
          'compat',
        )
      ).exitCode,
    ).toBe(0);
    const changeDir = path.join(dir, 'openspec/changes/demo');
    const stateFile = path.join(changeDir, '.comet.yaml');
    const state = parse(await fs.readFile(stateFile, 'utf8'));
    await fs.writeFile(stateFile, stringify({ ...state, phase: 'build' }));
    await fs.writeFile(path.join(changeDir, 'tasks.md'), '- [x] work <!-- comet-task:a -->\n');
    await fs.writeFile(path.join(changeDir, 'proposal.md'), '# Proposal\n');
    await fs.writeFile(
      path.join(dir, 'package.json'),
      JSON.stringify({ name: 'root', private: true, workspaces: ['packages/*'] }),
    );
    await fs.mkdir(path.join(dir, 'packages', 'app'), { recursive: true });
    await fs.writeFile(
      path.join(dir, 'packages', 'app', 'package.json'),
      JSON.stringify({ name: 'app', scripts: { build: 'node -e "process.exit(0)"' } }),
    );
    const result = await cli('guard', 'demo', 'build');
    expect(result.exitCode, result.stderr).toBe(0);
    expect(result.stderr).toContain(
      "guard auto-ran the detected command 'npm --prefix packages/app run build'",
    );
  })
